CREATE TYPE public.swarm_consensus AS ENUM ('Majority_Vote','Weighted_Elo','Hierarchical_Judge','Zero_Trust_Cross_Verification');
CREATE TYPE public.merge_method AS ENUM ('SLERP','DARE','TIES','Passthrough','Frankenmerge');
CREATE TYPE public.merge_status AS ENUM ('compiling','benchmarking','published','failed');
CREATE TYPE public.pqc_algorithm AS ENUM ('CRYSTALS-Dilithium','Falcon','SPHINCS+');
CREATE TYPE public.pqc_status AS ENUM ('Valid','Corrupted','Replay_Attack_Blocked');
CREATE TABLE public.swarm_topologies (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), org_id uuid NOT NULL REFERENCES public.organizations(id), name text NOT NULL, orchestrator_model_id text NOT NULL REFERENCES public.ai_models(id), node_assignments jsonb NOT NULL DEFAULT '[]', consensus_protocol public.swarm_consensus NOT NULL DEFAULT 'Majority_Vote', overall_tps numeric NOT NULL DEFAULT 0, cost_per_execution_usd numeric NOT NULL DEFAULT 0, graph jsonb NOT NULL DEFAULT '{}', source text NOT NULL DEFAULT 'local-planner', created_at timestamptz NOT NULL DEFAULT now());
GRANT SELECT,INSERT,UPDATE,DELETE ON public.swarm_topologies TO authenticated;
GRANT ALL ON public.swarm_topologies TO service_role;
ALTER TABLE public.swarm_topologies ENABLE ROW LEVEL SECURITY;
CREATE POLICY "members read swarms" ON public.swarm_topologies FOR SELECT TO authenticated USING (public.is_org_member(org_id,auth.uid()));
CREATE POLICY "managers write swarms" ON public.swarm_topologies FOR ALL TO authenticated USING (public.can_manage_org(org_id,auth.uid())) WITH CHECK (public.can_manage_org(org_id,auth.uid()));
CREATE TABLE public.model_merge_recipes (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), org_id uuid NOT NULL REFERENCES public.organizations(id), parent_model_ids jsonb NOT NULL DEFAULT '[]', merge_method public.merge_method NOT NULL, layer_weight_distribution jsonb NOT NULL DEFAULT '{}', merged_model_name text NOT NULL, benchmark_gain_delta jsonb NOT NULL DEFAULT '{}', status public.merge_status NOT NULL DEFAULT 'compiling', source text NOT NULL DEFAULT 'unexecuted-recipe', created_at timestamptz NOT NULL DEFAULT now());
GRANT SELECT,INSERT,UPDATE,DELETE ON public.model_merge_recipes TO authenticated;
GRANT ALL ON public.model_merge_recipes TO service_role;
ALTER TABLE public.model_merge_recipes ENABLE ROW LEVEL SECURITY;
CREATE POLICY "members read recipes" ON public.model_merge_recipes FOR SELECT TO authenticated USING (public.is_org_member(org_id,auth.uid()));
CREATE POLICY "managers write recipes" ON public.model_merge_recipes FOR ALL TO authenticated USING (public.can_manage_org(org_id,auth.uid())) WITH CHECK (public.can_manage_org(org_id,auth.uid()));
CREATE TABLE public.pqc_telemetry_verifications (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), org_id uuid NOT NULL REFERENCES public.organizations(id), probe_node_id text NOT NULL, algorithm public.pqc_algorithm NOT NULL, public_key_fingerprint text NOT NULL, verification_status public.pqc_status NOT NULL, payload_hash text NOT NULL, source text NOT NULL DEFAULT 'server-verified-import', timestamp timestamptz NOT NULL DEFAULT now());
GRANT SELECT ON public.pqc_telemetry_verifications TO authenticated;
GRANT ALL ON public.pqc_telemetry_verifications TO service_role;
ALTER TABLE public.pqc_telemetry_verifications ENABLE ROW LEVEL SECURITY;
CREATE POLICY "members read verifications" ON public.pqc_telemetry_verifications FOR SELECT TO authenticated USING (public.is_org_member(org_id,auth.uid()));
CREATE INDEX phase7_swarm_org ON public.swarm_topologies(org_id,created_at DESC);
CREATE INDEX phase7_recipe_org ON public.model_merge_recipes(org_id,created_at DESC);
CREATE INDEX phase7_pqc_org ON public.pqc_telemetry_verifications(org_id,timestamp DESC);
COMMENT ON TABLE public.model_merge_recipes IS 'Unexecuted local recipes; status compiling does not imply a running compute job. No benchmark gain is asserted until measured.';
COMMENT ON TABLE public.pqc_telemetry_verifications IS 'Server-issued verification records only. Client imports cannot assert validity. Signature validity alone does not certify provider SLA truth.';